const D = { scale:1, density:.5, energy:.55, speed:1, sag:.5, hue:32, x:.5, y:.5, style:'jute', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width,height), t=K.t, sty=P.style;
const hsh = i => { const s = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return s - Math.floor(s); };
const cols = Math.max(5, Math.min(12, Math.round(6 + P.density*7)));
const Rr = Math.max(6, Math.min(13, Math.round(6 + P.density*8)));
const gridW = width*0.82, x0=width*0.09;
const spX = gridW/cols, rowH=(height*0.70)/Rr;
const cw = Math.max(2, (0.010+0.012*P.energy)*u*P.scale);
const pivX=width*0.5, pivY=height*0.06;
const swayA = (0.02+0.05*P.energy)*(0.8*Math.sin(t*(0.4+P.speed*0.5)) + 0.4*Math.sin(t*0.83+1.1));
const cs=Math.cos(swayA), sn=Math.sin(swayA);
const bass=Math.min(0.5,A.bass*0.6);

if (sty==='blueprint') background(214,58,17);
else if (sty==='monochrome') background(32,10,55);
else background(28,34,9);

// node positions with jitter + rigid pendulum sway about top anchor
const nodes=[];
for (let r=0;r<=Rr;r++){
  nodes[r]=[];
  for (let c=0;c<=cols;c++){
    let bx=x0 + c*spX + (r%2)*spX*0.5;
    let by=height*0.10 + r*rowH;
    const j=0.02*u*P.scale;
    bx += j*Math.sin(by*0.02 + t*1.1 + c*0.7);
    by += j*0.5*Math.sin(bx*0.02 + t*0.9 + r*0.5);
    const dx=bx-pivX, dy=by-pivY;
    nodes[r][c]={ x: pivX + dx*cs - dy*sn, y: pivY + dx*sn + dy*cs };
  }
}
function cordCol(hu){
  if (sty==='monochrome') return {ca:[32,14,20], co:[32,8,78]};
  if (sty==='blueprint') return {ca:[200,64,32], co:[192,22,90]};
  if (sty==='boho') return {ca:[hu,60,26], co:[hu,44,72]};
  if (sty==='neon') return {ca:[hu,80,26], co:[hu,45,92]};
  return {ca:[(P.hue-4)%360,42,20+8*bass], co:[(P.hue+2)%360,30,66+8*bass]};
}
function cord(a,b,hu){
  const mx=(a.x+b.x)/2, my=(a.y+b.y)/2, len=Math.hypot(b.x-a.x,b.y-a.y), sag=len*(0.10+0.22*P.sag);
  const cc=cordCol(hu);
  if (sty==='blueprint'){ noFill(); stroke(cc.ca[0],cc.ca[1],cc.ca[2],P.alpha); strokeWeight(cw*0.7); beginShape(); vertex(a.x,a.y); quadraticVertex(mx,my+sag,b.x,b.y); endShape(); return; }
  if (sty==='neon'){ blendMode(ADD); noFill(); stroke(cc.ca[0],cc.ca[1],cc.ca[2]*0.6,30*(P.alpha/100)); strokeWeight(cw*1.6); beginShape(); vertex(a.x,a.y); quadraticVertex(mx,my+sag,b.x,b.y); endShape(); stroke(cc.co[0],cc.co[1],cc.co[2],80*(P.alpha/100)); strokeWeight(cw*0.4); beginShape(); vertex(a.x,a.y); quadraticVertex(mx,my+sag,b.x,b.y); endShape(); blendMode(BLEND); return; }
  noFill(); strokeCap(ROUND);
  stroke(cc.ca[0],cc.ca[1]+6,cc.ca[2]*0.6,P.alpha); strokeWeight(cw*1.15); beginShape(); vertex(a.x,a.y); quadraticVertex(mx,my+sag,b.x,b.y); endShape();
  stroke(cc.co[0],cc.co[1],cc.co[2],P.alpha); strokeWeight(cw*0.5); beginShape(); vertex(a.x,a.y); quadraticVertex(mx,my+sag,b.x,b.y); endShape();
}
// top anchor bar
noFill(); stroke(sty==='blueprint'?200:sty==='monochrome'?32:(P.hue-6)%360, sty==='blueprint'?50:44, sty==='monochrome'?30:46, P.alpha); strokeWeight(cw*1.6);
line(width*0.14, nodes[0][0].y-rowH*0.4, width*0.86, nodes[0][cols].y-rowH*0.4);
for (let c=0;c<=cols;c++){ const n=nodes[0][c]; stroke((P.hue-4)%360,40,40,P.alpha*0.8); strokeWeight(cw*0.8); line(n.x, nodes[0][0].y-rowH*0.4, n.x, n.y); }

// diamond net cords
for (let r=0;r<Rr;r++){
  for (let c=0;c<=cols;c++){
    const hu=(P.hue + (r*7 + c*23))%360;
    const dir = (r%2)? 1 : -1;
    if (nodes[r+1][c]) cord(nodes[r][c], nodes[r+1][c], hu);
    const c2=c+dir;
    if (c2>=0 && c2<=cols && nodes[r+1][c2]) cord(nodes[r][c], nodes[r+1][c2], hu);
  }
}
// knot bumps at nodes
for (let r=0;r<=Rr;r++){ for (let c=0;c<=cols;c++){ const n=nodes[r][c];
  if (sty==='blueprint'){ noStroke(); fill(190,30,88,80*(P.alpha/100)); ellipse(n.x,n.y,cw*1.4,cw*1.4); continue; }
  const cc=cordCol((P.hue+c*17)%360); push(); translate(n.x,n.y); rotate((r+c)*0.5);
  strokeCap(ROUND); stroke(cc.ca[0],cc.ca[1],cc.ca[2]*0.7,P.alpha); strokeWeight(cw*1.6); line(-cw*1.3,0,cw*1.3,0);
  stroke(cc.co[0],cc.co[1],Math.min(100,cc.co[2]+10),P.alpha); strokeWeight(cw*0.7); line(-cw*1.1,-cw*0.3,cw*1.1,-cw*0.3);
  pop();
}}
// fringe + tassels at bottom
for (let c=0;c<=cols;c++){ const n=nodes[Rr][c]; const fl=rowH*(1.1+0.6*hsh(c*3+1));
  const sw=(0.06+0.10*P.energy)*fl*Math.sin(t*(0.6+P.speed*0.6)+c*0.6);
  const ex=n.x+sw, ey=n.y+fl;
  const cc=cordCol((P.hue+c*13)%360);
  if (sty!=='blueprint'){ noFill(); strokeCap(ROUND); stroke(cc.ca[0],cc.ca[1],cc.ca[2]*0.7,P.alpha); strokeWeight(cw*0.9); beginShape(); vertex(n.x,n.y); quadraticVertex(n.x+sw*0.5,(n.y+ey)/2,ex,ey); endShape();
    for (let k=-1;k<=1;k++){ stroke(cc.co[0],cc.co[1],cc.co[2],P.alpha*0.8); strokeWeight(cw*0.5); line(ex,ey, ex+k*cw*1.2, ey+fl*0.28); } }
  else { stroke(200,50,60,P.alpha*0.7); strokeWeight(cw*0.5); line(n.x,n.y,ex,ey); }
}
